repo.fixtures.py:
"""Fixture records."""


class Fixture:
    def __init__(self, club, goals):
        self.club = club
        self.goals = goals

    def __repr__(self):
        return "Fixture(%r, %r)" % (self.club, self.goals)


ROWS = [('city', 15), ('united', 25), ('rovers', 18), ('rovers', 17), ('rovers', 22), ('city', 34), ('rovers', 54)]


def load_fixtures():
    """Yield the stored fixtures one at a time."""
    for club, goals in ROWS:
        yield Fixture(club, goals)

repo.settle.py:
"""Checking that fixtures add up."""


def is_settled(fixtures, expected_total):
    """Return True when the goals of the fixtures add up to expected_total. goals may be fractional."""
    return sum(x.goals for x in fixtures) == expected_total


def shortfall(fixtures, expected_total):
    """Return how much goals is still missing, never less than 0."""
    return max(0, expected_total - sum(x.goals for x in fixtures))


def group_by_club(fixtures):
    """Return a dict from club to the list of fixtures with that club."""
    groups = {}
    for x in fixtures:
        groups.setdefault(x.club, []).append(x)
    return groups


def largest_goals(fixtures):
    """Return the largest goals, or None when there are no fixtures."""
    values = [x.goals for x in fixtures]
    return max(values) if values else None

