from fixtures import Fixture
from settle import is_settled


def test_tenths():
    assert is_settled([Fixture("a", 0.1), Fixture("b", 0.2)], 0.3)


def test_whole_numbers():
    assert is_settled([Fixture("a", 2), Fixture("b", 3)], 5)
